import type { ReactElement } from 'react';
import { useFolderBrowser, type FolderBrowser } from './useFolderBrowser';
import { panelStyle } from './styles';

export type Folder = { id: string; name: string; children: Folder[] };
export type Props = { folders: Folder[]; onNavigate: (path: string[]) => void };

export function Component({ folders, onNavigate }: Props): ReactElement {
  const browser: FolderBrowser = useFolderBrowser(folders, onNavigate);

  return (
    <section data-testid="panel" style={panelStyle}>
      <output aria-label="Current path">{browser.currentPath}</output>
      <button type="button" disabled={browser.path.length === 0} onClick={browser.back}>Back</button>
      <ul aria-label="Folders">
        {browser.children.map((folder: Folder): ReactElement => (
          <li key={folder.id}>
            <button type="button" onClick={(): void => browser.enter(folder.id)}>
              {`Enter ${folder.name}`}
            </button>
          </li>
        ))}
      </ul>
      {browser.children.length === 0 && <p role="status">No folders</p>}
    </section>
  );
}

